def find_bar(g):
    H,W=len(g),len(g[0])
    for r in range(H-2):
        for c in range(W):
            v=g[r][c]
            if v and all(g[r+i][c]==v for i in range(3)):
                # horizontal extent
                c2=c
                while c2+1<W and g[r][c2+1]==v: c2+=1
                if c2-c+1>=3: return (r,c)
    return None
def transform(g):
    H,W=len(g),len(g[0])
    br,bc=find_bar(g)
    barcolor=g[br][bc]
    order=[]; r=br
    while r>=0 and g[r][bc]!=0: order.append(g[r][bc]); r-=1
    order=order[::-1]; r=br+1
    while r<H and g[r][bc]!=0: order.append(g[r][bc]); r+=1
    from collections import defaultdict
    cells=defaultdict(list)
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v not in (0,barcolor): cells[v].append((i,j))
    out=[row[:] for row in g]
    anchor=None
    for col in order:
        if cells[col]:
            rs=[p[0] for p in cells[col]]; cs=[p[1] for p in cells[col]]
            anchor=(min(rs),min(cs),max(rs),max(cs)); anchorcol=col; break
    r0,c0,r1,c1=anchor; hgt=r1-r0+1
    idx=order.index(anchorcol)
    top=r0-idx*hgt
    for k,col in enumerate(order):
        if col==anchorcol or cells.get(col): continue
        tr=top+k*hgt
        for (i,j) in cells[anchorcol]:
            out[tr+(i-r0)][j]=col
    return out
