def transform(g):
    H,W=len(g),len(g[0])
    br=bc=None
    for r in range(H-2):
        for c in range(W-2):
            if g[r][c] and all(g[r+i][c]==g[r][c] for i in range(3)) and all(g[r+i][c+j]!=0 and g[r+i][c+j]==g[r][c+j] for i in range(3) for j in range(3)):
                br,bc=r,c; break
        if br is not None: break
    cols=[bc]; c=bc-1
    while c>=0 and g[br][c]!=0 and all(g[r][c]==g[br][c] for r in range(br,br+3)): cols.append(c); c-=1
    c=bc+1
    while c<W and g[br][c]!=0 and all(g[r][c]==g[br][c] for r in range(br,br+3)): cols.append(c); c+=1
    cols=sorted(cols); order=[g[br][cc] for cc in cols]
    barcells=set((r,cc) for r in range(br,br+3) for cc in cols)
    from collections import defaultdict
    cells=defaultdict(list)
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v!=0 and (i,j) not in barcells: cells[v].append((i,j))
    out=[[0]*W for _ in range(H)]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if (i,j) not in barcells: out[i][j]=v
    for col in order:
        if cells[col]:
            rs=[p[0] for p in cells[col]]; cs=[p[1] for p in cells[col]]
            anchor=(min(rs),min(cs),max(rs),max(cs),col); break
    r0,c0,r1,c1,ac=anchor; hgt=r1-r0+1
    top=r0-order.index(ac)*hgt
    for k,col in enumerate(order):
        if cells.get(col): continue
        tr=top+k*hgt
        for (i,j) in cells[ac]:
            out[tr+(i-r0)][j]=col
    return out
